                },
                "evermonkey.noteStoreUrl": {
                    "type": "string",
                    "default": "",
                    "description": "Copy your NoteStore URL from the website. (ever token: Open Developer Page)"
                },
                "evermonkey.highlightTheme": {
                    "type": "string",
                    "default": "github",
