                    ],
                    "description": "Evernote custom render. Will override the markdown theme."
                },
                "evermonkey.fontSize": {
                    "type": "string",
                    "default": "16px",
                    "description": "Evernote custom render. Will override the markdown theme."
                },
                "evermonkey.codeFontFamily": {
                    "type": "array",
                    "default": [
                        "Helvetica Neue",
